    function countNested(items, keys) {
      return asArray(items).reduce((sum, item) => {
        for (const key of keys) {
          if (Array.isArray(item && item[key])) return sum + item[key].length;
          if (typeof (item && item[key + "Count"]) === "number") return sum + item[key + "Count"];
        }
        return sum;
      }, 0);
    }

    function countSupplements(memories) {
      return asArray(memories).reduce((sum, memory) => {
        if (typeof memory.supplementCount === "number") return sum + memory.supplementCount;
        const direct = asArray(memory.supplements).length;
        const nested = asArray(memory.segments).reduce((segmentSum, segment) => {
          if (typeof segment.supplementCount === "number") return segmentSum + segment.supplementCount;
          return segmentSum + asArray(segment.supplements).length;
        }, 0);
        return sum + direct + nested;
      }, 0);
    }

    function countWorks(memories) {
      return asArray(memories).reduce((sum, memory) => {
        if (typeof memory.workCount === "number") return sum + memory.workCount;
        const direct = asArray(memory.works).length + asArray(memory.artifacts).length;
        const segmentWorks = asArray(memory.segments).filter((segment) => segment && (segment.kind === "artifact" || segment.format === "html")).length;
        return sum + direct + segmentWorks;
      }, 0);
    }

    function countNeedsReview(root) {
      if (typeof (root && root.needsReviewCount) === "number") return root.needsReviewCount;
      if (Array.isArray(root && root.needsReview)) return root.needsReview.length;
      if (Array.isArray(root && root.reviewItems)) return root.reviewItems.length;
      return 0;
    }

    function normalizeWorkspace(payload) {
      const root = payload && (payload.workspace || payload);
      const memories = asArray(root && root.memories);
      const widgets = asArray(root && root.widgets);
      const currentMemory = payload && (payload.currentMemory || root.currentMemory) || null;
      return { root, memories, widgets, currentMemory };
    }

    function setStatus(text) {
      els.status.hidden = !text;
      els.status.textContent = text || "";
    }

    function render() {
      const data = workspaceData || { memories: [], widgets: [], currentMemory: null, root: {} };
      const memories = data.memories;
      const query = (durableState.stores.ui.query || "").trim().toLowerCase();
      const currentId = data.currentMemory && data.currentMemory.id;
      const filtered = memories.filter((memory) => {
        const title = pickTitle(memory, "未命名记忆").toLowerCase();
        const id = String(memory.id || "").toLowerCase();
        return !query || title.includes(query) || id.includes(query);
      });

      els.memoryCount.textContent = fmt.format(memories.length);
      els.segmentCount.textContent = fmt.format(typeof data.root.segmentCount === "number" ? data.root.segmentCount : countNested(memories, ["segments"]));
      els.supplementCount.textContent = fmt.format(typeof data.root.supplementCount === "number" ? data.root.supplementCount : countSupplements(memories));
      els.workCount.textContent = fmt.format(typeof data.root.workCount === "number" ? data.root.workCount : countWorks(memories));
      els.widgetCount.textContent = fmt.format(typeof data.root.widgetCount === "number" ? data.root.widgetCount : data.widgets.length);
      els.reviewCount.textContent = fmt.format(countNeedsReview(data.root));
      els.query.value = durableState.stores.ui.query || "";

      if (!filtered.length) {
        els.list.innerHTML = '<div class="empty">没有匹配的记忆</div>';
        return;
      }

      els.list.replaceChildren(...filtered.map((memory) => {
        const button = document.createElement("button");
        const memoryId = memory.id || "";
        const segments = typeof memory.segmentCount === "number" ? memory.segmentCount : asArray(memory.segments).length;
        const supplements = typeof memory.supplementCount === "number" ? memory.supplementCount : asArray(memory.supplements).length;
        button.type = "button";
        button.className = "memory-button" + (memoryId && memoryId === currentId ? " active" : "");
        button.dataset.memoryId = memoryId;
        button.innerHTML = '<span class="memory-main"><span class="memory-title"></span><span class="memory-meta"></span></span><span class="open-mark" aria-hidden="true">›</span>';
        button.querySelector(".memory-title").textContent = pickTitle(memory, "未命名记忆");
        button.querySelector(".memory-meta").textContent = `${fmt.format(segments)} segments · ${fmt.format(supplements)} supplements`;
        button.addEventListener("click", () => selectMemory(memoryId));
        return button;
      }));
    }

    async function saveUi(patch) {
      durableState = {
        ...durableState,
        stores: {
          ...durableState.stores,
          ui: { ...(durableState.stores && durableState.stores.ui || {}), ...patch }
        }
      };
      render();
      if (!window.reo || !window.reo.state || typeof window.reo.state.write !== "function") return;
      try {
        const saved = await window.reo.state.write(durableState, { baselineVersion: stateVersion });
        if (saved && saved.state) durableState = saved.state;
        if (saved && Object.prototype.hasOwnProperty.call(saved, "version")) stateVersion = saved.version;
      } catch (error) {
        setStatus("状态保存失败，列表仍可继续使用。");
      }
    }

    async function selectMemory(memoryId) {
      if (!memoryId) return;
      setStatus("");
      await saveUi({ lastSelectedMemoryId: memoryId });
      if (!window.reo || !window.reo.ui || typeof window.reo.ui.selectMemory !== "function") {
        setStatus("当前环境没有可用的 Reo bridge，无法切换主内容。");
        return;
      }
      try {
        await window.reo.ui.selectMemory({ memoryId });
        await loadWorkspace();
      } catch (error) {
        setStatus(error && error.message ? error.message : "打开记忆失败。");
      }
    }

    async function loadState() {
      if (!window.reo || !window.reo.state || typeof window.reo.state.read !== "function") return;
      try {
        const snapshot = await window.reo.state.read();
        if (snapshot && snapshot.state) durableState = snapshot.state;
        if (snapshot && Object.prototype.hasOwnProperty.call(snapshot, "version")) stateVersion = snapshot.version;
      } catch (error) {
        setStatus("读取状态失败，使用默认视图。");
      }
    }

    async function loadWorkspace() {
      if (!window.reo || !window.reo.workspace || typeof window.reo.workspace.read !== "function") {
        workspaceData = { memories: [], widgets: [], currentMemory: null, root: {} };
        render();
        setStatus("当前环境没有可用的 Reo bridge。");
        return;
      }
      try {
        const payload = await window.reo.workspace.read();
        workspaceData = normalizeWorkspace(payload);
        render();
        setStatus("");
      } catch (error) {
        workspaceData = { memories: [], widgets: [], currentMemory: null, root: {} };
        render();
        setStatus(error && error.message ? error.message : "读取 workspace 失败。");
      }
    }

    els.query.addEventListener("input", () => saveUi({ query: els.query.value }));
    els.refresh.addEventListener("click", loadWorkspace);

